INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('eingangssysteme.funktionalitaet','card_accessControl','description','en','Access to the building can be conveniently organised for recurring users with the help of electronic access control. The technology ranges from a code lock and transponder reader to a biometric fingerprint scanner.') ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value;
