INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('eingangssysteme.funktionalitaet','card_verwahrung','subtitle','en','Letterbox, parcel box and key safe') ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('eingangssysteme.funktionalitaet','card_verwahrung','description','de','Die sichere Verwahrung von Postgut oder von Schlüsseln für Sicherheits- und Rettungskräfte erfordert technische Lösungen. Neben Briefkasten und Paketbox können auch Schlüsseldepots namhafter Hersteller in eine Entry-Installation integriert werden.') ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('eingangssysteme.funktionalitaet','card_verwahrung','description','en','The secure storage of mail or of keys for security and rescue services requires technical solutions. In addition to letterboxes and parcel boxes, key safes from well-known manufacturers can also be integrated into an Entry installation.') ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value;
