INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('eingangssysteme.standards','card_unterputzmontage','description','de','In dieser Unterputzmontage ist die Front von einem Rahmen eingefasst. Dieser Rahmen überdeckt bis auf die Umlauffuge den Putzanschluss des Einfassungskastens.') ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value;
