INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('eingangssysteme.standards','card_inputzmontage','description','de','Bei einer Montage in Putz wird die Metallbauinstallation in einem Fassungsrahmen vollständig in die Wand integriert. Die Front aus 3 mm starkem Edelstahl wird putzbündig in den 2 mm starken Fassungsrahmen eingelassen.') ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('eingangssysteme.standards','card_inputzmontage','description','en','With flush-mount installation, the metalwork installation is fully integrated into the wall within a mounting frame. The 3 mm thick stainless steel front is set flush with the plaster into the 2 mm thick mounting frame.') ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value;
